"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Uma distância de início / fim transforma a aba em uma aba parcial. Os demais perfis fechados do esboço viram recortes na placa. Furos e janelas em uma aba: centro ao longo da aresta (em uma aresta curva, ao longo do arco), centro a partir do fim da dobra, tamanho – eles também aparecem na planificação. Se uma aresta curva passa sem quebra para a aresta vizinha e ambas têm uma aba com o mesmo ângulo de dobra, as abas se unem sem corte de alívio. „Contorno de esboço“ recorta da aba os perfis fechados de um esboço: seu X corre ao longo da aresta, seu Y para dentro da aba, e a origem fica no início da aresta, no fim da dobra (deslocável).",
