"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Selecione todas as faces que devem desaparecer (em uma cavidade, paredes e fundo; em um furo, a parede; em uma concordância, a face arredondada). As faces vizinhas são estendidas sobre a lacuna. A etapa é recalculada quando o corpo muda; na primeira vez, o núcleo geométrico completo é carregado para isso (alguns segundos).",
