"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Com “Furos”, a peça apoia-se na face, na extremidade do furo mais próxima do ponto clicado. Clique em vários furos, um após o outro, e depois em “Concluído”.",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Com “Furos”, a peça fica rente na extremidade do furo mais próxima do ponto clicado. Clique em vários furos, um após o outro, e depois em “Concluído”.",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Com “Furos”, a cabeça fica no lado do furo mais próximo do ponto clicado; a haste entra no furo. Clique em vários furos, um após o outro, e depois em “Concluído”.",
