"Darstellung der Körper":"Exibição dos corpos",
"Darstellung wird aufbereitet …":"Preparando a exibição …",
"Darstellung zurückgesetzt (vom Material).":"Aparência redefinida (do material).",
"Darstellung „{0}“ auf {1} Körper angewendet.":"Aparência “{0}” aplicada a {1} corpo(s).",
"Darstellungsqualität":"Qualidade de exibição",
"Das Bild konnte nicht gelesen werden.":"Não foi possível ler a imagem.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"A imagem está no plano como modelo. Depois, ajuste tamanho, posição, rotação e opacidade na janela de propriedades (p. ex. largura conforme uma dimensão conhecida).",
"Das Ergebnis des Geometriekerns ist unlesbar":"O resultado do núcleo geométrico é ilegível",
"Das Ergebnis konnte nicht geschrieben werden":"Não foi possível gravar o resultado",
"Das Maß muss größer als 0 sein.":"A cota deve ser maior que 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"A malha permanece uma malha de triângulos (não é B-Rep). Edição em MALHA: Reparar, Reduzir, Suavizar, Corte por plano … As estratégias de fresamento 3D em Manufatura podem usinar a malha diretamente.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"A malha tem {0} triângulos. Cada um vira uma face do corpo – isso demora e deixa o corpo lento. Normalmente é melhor usar «Reduzir» antes.\n\nConverter mesmo assim?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"A malha não está fechada. Execute primeiro «Reparar» – um corpo precisa de um invólucro fechado.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"A malha se estende em Z de {0} a {1} mm, em X de {2} a {3} mm, em Y de {4} a {5} mm. Pontos que se desviam de uma reta menos que a tolerância são descartados.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"O perfil não pode cruzar o eixo. Uma linha aberta no esboço pode servir de eixo.",
"Das Profil mit den jetzigen Werten überschreiben":"Sobrescrever o perfil com os valores atuais",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"O perfil é conduzido ao longo de uma linha/polilinha. O ideal é desenhar o perfil perpendicular ao início da trajetória (p. ex. perfil em XZ, trajetória em XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"O perfil é gravado em relevo ou rebaixado a partir do plano do esboço.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"O bruto é o paralelepípedo em volta do corpo selecionado (mais o deslocamento).",
"Das Setup hat keine Operationen.":"O setup não tem operações.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"A ferramenta fresa em círculos cujo centro se desloca ao longo do rasgo. Nunca está engajada em toda a largura – isso permite grandes profundidades de passe e poupa a fresa e o fuso. A fresa deve ter cerca de 60 % da largura do rasgo.",
"Das Werkzeug schneidet die Fläche nicht":"A ferramenta não intersecta a superfície",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"A ferramenta corta em direção às faces selecionadas até atingir os sobremetais indicados.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"A ferramenta mergulha na vertical como uma broca, fileira por fileira, até o modelo mais o sobremetal. A força de corte atua ao longo do fuso: adequado para ferramentas longas, cavidades profundas e máquinas pouco rígidas. A ferramenta deve cortar no centro.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"A ferramenta evita essas faces respeitando as distâncias de segurança indicadas (grampos, morsa).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"A ferramenta evita essas faces ao usinar faces próximas e respeita as distâncias de segurança.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"O primeiro Esc cancela apenas a ferramenta ou a seleção – um Esc a mais não fecha o esboço",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Isto não é um furo (concordância ou pino) – clique na parede interna de um furo.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Isto não é um furo (face cilíndrica) – clique na parede do furo.",
"Das ist keine WerkFab-Design-Datei.":"Este não é um arquivo de tema do WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Esta não é uma aresta inclinada – clique nas duas extremidades da aresta do chanfro.",
"Datei":"Arquivo",
"Datei ist keine WerkFab-Einstellungsdatei.":"O arquivo não é um arquivo de configurações do WerkFab.",
"Datei konnte nicht geöffnet werden:":"Não foi possível abrir o arquivo:",
"Dateiendung":"Extensão do arquivo",
