"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Este navegador não oferece suporte a SpaceMouse (WebHID). Use o Chrome, o Edge ou o aplicativo desktop.",
"Dieser Schritt braucht einen Körper des Standardkerns":"Esta etapa precisa de um corpo do núcleo padrão",
"Dieses Feature steht nicht im Browser (nur Skizzen und Körper werden dort gezeigt).":"Este recurso não aparece no navegador (somente esboços e corpos são exibidos ali).",
"Dieses Gelenk bewegt sich mit dem gewählten (z. B. Zahnräder: Übersetzung = −Zähne₁/Zähne₂). Negative Werte drehen gegenläufig.":"Esta junta se move junto com a selecionada (p. ex., engrenagens: relação = −dentes₁/dentes₂). Valores negativos giram em sentido contrário.",
