"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Torneamento: a peça deve ser simétrica em rotação em torno do eixo Z. Z0 = face frontal no topo, X = diâmetro.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Girar: clique no ponto de rotação e depois indique o ângulo com o mouse (pré-visualização). Esc encerra.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Torneamento: diâmetro em que a torre indexa (Okuma, LinuxCNC). 0 = Ø do bruto + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Girar: selecione elementos, clique no ponto de rotação e indique o ângulo com o mouse (pré-visualização); também como cópia",
"Drehen: Gewindeschnitt":"Torneamento: passe de rosca",
"Drehen: Gewindezyklus":"Torneamento: ciclo de rosca",
"Drehen: Polar-Interpolation aus":"Torneamento: interpolação polar desligada",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Torneamento: interpolação polar ligada (X diâmetro, C em mm; vazio = X/C em graus)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Torneamento: ciclo de acabamento (contorno do ciclo de desbaste)",
