"Drehen: Vorsatz erste Konturzeile":"Torneamento: prefixo da primeira linha do contorno",
"Drehen: Vorsatz letzte Konturzeile":"Torneamento: prefixo da última linha do contorno",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Girar: ângulo (°, sentido anti-horário); ponto de rotação X; ponto de rotação Y; cópias (0 = girar)",
"Drehen: Y-Achse aus":"Torneamento: eixo Y desligado",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"Torneamento: eixo Y ligado (plano X/Y; informe aqui também o travamento C da máquina)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Torneamento: Z à frente da face em que a torre indexa. 0 = distância de segurança + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Torneamento: interpolação cilíndrica desligada",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Torneamento: interpolação cilíndrica ligada ({cylr} = raio; vazio = Z/C sem)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Torneamento: ferramenta motorizada e eixo C desligados",
"Drehen: einen Winkel angeben.":"Girar: informe um ângulo.",
