"Drehgeschwindigkeit":"Velocidade de rotação",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Torno com eixo Y: chaves de boca, contornos e cavidades na face são usinados com a peça parada (C fixo) em X e Y – com mais precisão que a interpolação polar. O que ultrapassa o curso Y permanece com a interpolação polar.",
