"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Furo extrudado {0}: o pré-furo Ø {1} mm é alargado para Ø {2} mm (fator {3}) – a borda geralmente rasga.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Furo extrudado {0}: o pré-furo Ø {1} mm é alargado para Ø {2} mm (fator {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Furo extrudado {0}: fica a {1} mm da borda (menos de 2 × a espessura da chapa) – a borda estufa.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Furo extrudado {0}: alto demais para este furo (o pré-furo ficaria sem diâmetro)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Furo extrudado: a borda de um furo redondo é puxada para cima formando um colarinho, por exemplo como furo extrudado para rosca. O diâmetro do furo no esboço é o diâmetro interno final; no blank é cortado o pré-furo, menor.",
