"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Atalhos personalizados: abra o menu do grupo (▾) na barra de ferramentas, clique em ⋮ ao lado do comando → “Alterar atalho de teclado …”.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Cotas e notas próprias podem ser arrastadas na folha com o mouse (distância da linha de cota, ângulo da linha de chamada, raio do arco do ângulo). Clicar em dois cantos = cota linear. Clicar na borda de um círculo na vista superior = diâmetro (ou raio). Ângulo: primeiro o vértice, depois um ponto de canto em cada lado. Chanfro: ambas as extremidades da aresta inclinada – resulta, p. ex., em 2×45°. No campo de texto após cada cota há um complemento como ±0,1, H7 ou 4×.",
