"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Uma fresa redonda deixa seu raio em cada canto interno – uma peça de encaixe angular não entra. O alívio avança brevemente para o canto e volta em cada canto interno vivo.{0}{1}",
