"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Clique primeiro na face do corpo que será movido e depois na face de destino do outro corpo. O corpo é girado e movido até que o primeiro ponto clicado fique sobre o segundo e as faces fiquem sobrepostas.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Clique primeiro na aresta do corpo que será movido e depois na aresta de destino do outro corpo. Arestas retas ficam coincidentes (centro sobre centro); em arestas circulares – furo e pino – os eixos são alinhados na mesma direção e os centros são unidos.",
"Erst ein Setup anlegen.":"Crie primeiro um setup.",
"Erst ein Setup mit Operationen anlegen.":"Crie primeiro um setup com operações.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Selecione primeiro um esboço ou plano de construção – então Ctrl+8 olha perpendicularmente para ele.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Crie primeiro um corpo em PROJETO ou insira uma malha (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Crie primeiro um corpo em PROJETO.",
"Erst einen Namen für das Profil eingeben.":"Digite primeiro um nome para o perfil.",
