"Fläche am bewegten Körper gewählt":"face no corpo movido selecionada",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Clique em uma face de um corpo: seu contorno entra no esboço. Clicar em uma aresta projeta somente essa aresta (círculos continuam círculos). A geometria projetada é roxa.",
"Fläche ersetzen":"Substituir face",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Substituir face: mover uma face plana para outro plano – o corpo cresce ou é encurtado",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Área atrás das janelas – vale quando o tema „Próprio“ está selecionado acima",
"Fläche löschen":"Excluir face",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Excluir face: remover furos, cavidades, concordâncias ou chanfros – as faces vizinhas fecham a lacuna",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Exibir em cor a face ou aresta sob o ponteiro do mouse",
"Fläche versetzen":"Deslocar face",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Deslocar face: mover faces planas, alterar o diâmetro de furos e pinos",
"Fläche wählen":"Selecionar face",
"Fläche wählen, die getrimmt wird":"Selecione a superfície a ser aparada",
"Fläche zum Antasten in Z":"Face para apalpação em Z",
"Fläche {0}":"Face {0}",
"Flächen":"Faces",
"Flächen (alle Kanten ringsum)":"Faces (todas as arestas ao redor)",
"Flächen (aufeinander legen)":"Faces (sobrepor)",
"Flächen am Körper":"Faces no corpo",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Faces planas na extremidade da peça (duas faces, quadrado, sextavado) com uma fresa de topo motorizada ao longo de Z. Abertura da chave = o dobro da distância da face ao eixo de rotação. X e C se movem juntos (interpolação polar, Fanuc G12.1); sem este modelo no pós-processador, são emitidos pequenos passos X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Clique nas faces a espessar (clicar novamente remove).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Clique nas faces a inclinar (clicar novamente remove).",
"Flächen anklicken, die offen sein sollen.":"Clique nas faces que devem ficar abertas.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Clique nas faces a deslocar (clicar novamente remove).",
"Flächen im Modell":"Faces no modelo",
