"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Linhas retas do esboço que não pertencem a nenhum perfil (também linhas auxiliares). Dobra: a linha é o centro da zona de dobra e o esboço ali é o blank – a maior parte da placa permanece no lugar, tudo além da linha gira junto com suas abas. A linha vale para a placa inteira. Nervura: uma costela ao longo da linha, redonda na seção e nas extremidades; a chapa mantém sua espessura.",
