"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Fechado: as abas em duas arestas vizinhas vão até a bissetriz do canto e deixam a folga ali. O alívio de canto fica onde as zonas de dobra se cruzam – na planificação e na peça dobrada. Uma aba em uma aresta curva também é cortada em meia-esquadria em um canto real (ali sem alívio de canto).",
