"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Perfis fechados viram superfícies planas – p. ex. tampa e fundo, para depois costurar as superfícies em um corpo.",
