"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Corpos importados não têm histórico de projeto, mas podem ser editados (concordância, chanfro, corte …) e usados no CAM. Com “Eixo Y para cima”, modelos de programas com Y para cima são posicionados corretamente.",
