"Interferenz":"Interferência",
"Interferenz braucht mindestens zwei Körper.":"Interferência precisa de pelo menos dois corpos.",
"Inventor (Mitte verschieben, Umschalt+Mitte drehen)":"Inventor (meio move, Shift+meio gira)",
"Invers Verschleiß":"Desgaste inverso",
"Invertieren (helle Linien auf dunklem Grund)":"Inverter (linhas claras em fundo escuro)",
