"Isometrische Ansicht":"Vista isométrica",
"J (relativ)":"J (relativo)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"A primeira curva de cada esboço – aberta ou fechada. As curvas são unidas por uma pele (superfície sem espessura).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Um arquivo por chapa-base. A trajetória corre ao lado do contorno, na sobra, afastada em meia largura de corte (no fresamento, meia fresa); os recortes vêm antes do contorno da sua peça e cada contorno começa com uma entrada de corte a partir da sobra. Ligar com M3 (laser: M3 S…), desligar com M5, tempo de perfuração como G4. A origem é o canto inferior esquerdo da chapa-base; no fresamento, Z0 é a face superior da chapa. Verifique o programa na máquina ou em um simulador NC antes de usá-lo.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Cada eixo separadamente: clique em uma aresta, canto, face ou furo. Eixos não definidos vêm do ponto do bruto.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Cada operação como subprograma (LBL) no fim do programa, chamada com CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Cada círculo do esboço é o centro de um furo. A furação é feita contra a normal do esboço (para dentro do material).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Cada círculo do esboço é repetido girando em torno do centro (em coordenadas do esboço) – um círculo à distância do raio do círculo primitivo resulta em um círculo de furos.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Cada círculo do esboço se torna uma grade: espaçamentos em X e Y do esboço (também negativos).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Agora um ponto no segundo lado.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Agora mova cada direção uma vez até o limite: deslizar, puxar, empurrar, inclinar, girar (10 s) …",
"Jetzt laden":"Baixar agora",
"Jetzt nach Updates suchen":"Verificar atualizações agora",
