"Kalibrieren: einen Abstand größer als 0 angeben.":"Calibrar: informe uma distância maior que 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Calibrar: clique no primeiro ponto da imagem (Esc cancela).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Calibrar: distância real entre os dois pontos (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibrar: clique em dois pontos da imagem cuja distância seja conhecida e informe a distância real – a imagem recebe a escala correta.",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"Calibrar: clique no segundo ponto da imagem (Esc cancela).",
