"Kante {0} (Kreis R{1}, {2} mm)":"Aresta {0} (círculo R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Aresta {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"A aresta {0} é curta demais para uma aba",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Aresta {0}: um ângulo de dobra acima de 180° não pode ser fabricado.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Aresta {0}: aba em uma aresta curva – sua borda é comprimida em {1} % durante a conformação (risco de rugas); o recorte é ali uma aproximação.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Aresta {0}: aba em uma aresta curva – sua borda é esticada em {1} % durante a conformação (risco de trincas); o recorte é ali uma aproximação.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Aresta {0}: a medida da aba {1} mm é menor que a dobra ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Aresta {0}: o arco é muito fechado para esta aba",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Aresta {0}: as distâncias não deixam nenhuma aba.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Aresta {0}: a aba cruza uma linha de dobra – faça-a terminar antes da dobra com “Distância início / fim”",
"Kante {0}: die Lasche liegt in einer Biegezone":"Aresta {0}: a aba está em uma zona de dobra",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Aresta {0}: um recorte pertence a uma aba que não existe.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Aresta {0}: um recorte na aba está a {1} mm da dobra (menos de 2 × a espessura da chapa) – ele se deforma ao dobrar.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Aresta {0}: um recorte está a {1} mm da dobra (menos de 2 × a espessura da chapa) – ele se deforma ao dobrar.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Aresta {0}: um recorte ultrapassa a aba.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Aresta {0}{1}: a aba de {2} mm é mais curta que 2 × a espessura da chapa – quase impossível de dobrar na dobradeira.",
"Kanten":"Arestas",
