"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Solte a tampa e escolha “Calibrar ponto zero”. Depois teste cada direção: a barra deve se mover e, em repouso, permanecer na zona morta cinza.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Deslizar a tampa = deslocar, empurrar/puxar = zoom, inclinar e girar = girar o modelo. Em esboços, somente deslocar e zoom. SpaceMouse Pro/Enterprise: T, F, R = vista superior, frontal, direita. Se nada acontecer: feche rapidamente o driver da 3Dconnexion e reconecte.",
