"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contorno com {0} pontos – Okuma: G85 (LAP) com contorno G81…G80, Fanuc: G71 P…Q…. O comando desbasta com sua própria divisão de passes; a simulação aqui é a trajetória do WerkFab.",
