"Konturen außen und innen":"Contornos externos e internos",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Os contornos seguem a borda das áreas escuras. A linha central percorre o meio dos traços – adequada para gravações e desenhos de linhas. “Retas, arcos e círculos” reconhece arestas retas, cantos vivos, arredondamentos e círculos; “Polilinhas” segue a imagem ponto a ponto. Depois, se necessário, ajuste a escala com “Calibrar modelo” ou “Escalar”.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Contornos com compensação de raio no comando (RL/RR) usam APPR/DEP para aproximação e afastamento; o comando calcula o ponto auxiliar e a compensação por conta própria",
