"Kurven":"Curvas",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Curvas de um esboço na face frontal (transversal ao eixo de rotação) com uma fresa motorizada ao longo de Z (X e C se movem juntos; Fanuc: interpolação polar G12.1). Curvas abertas são fresadas de ida e volta. Profundidade a partir da face frontal.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Curvas de um esboço situado ao longo do eixo de rotação são enroladas na circunferência e fresadas com uma fresa motorizada apontada para o eixo (Z e C se movem juntos; Fanuc: interpolação cilíndrica G7.1). O plano do esboço define o ângulo em que o contorno se encontra; trechos horizontais no esboço tornam-se arcos em volta da peça. Profundidade a partir do diâmetro externo.",
"Kurzbefehl":"Atalho",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Percursos curtos (até a distância de permanência) são feitos embaixo com o avanço de transição, em vez de pela altura de recuo – sem verificação de colisão, portanto mantenha pequeno.",
