"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Selecione o material no setup em „Bruto → Material do bruto“. A densidade fornece o peso do bruto, Vc é um valor de referência para metal duro; a cor é mostrada na simulação.",
