"Mehrere Schlichtdurchgänge":"Várias passadas de acabamento",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Várias arestas encadeadas contam como um único trecho: o raio vai do início da cadeia até o seu fim, e os pontos de controle valem em % do comprimento total da cadeia. Isto é calculado pelo núcleo geométrico completo.",
