"Mit Netzkörper":"Com corpo de malha",
"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Com pontos de controle, o raio passa pelos valores informados (posição em % do comprimento da aresta). Isto é calculado pelo núcleo geométrico completo; na primeira vez ele leva alguns segundos para carregar.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Não é possível usinar com o apalpador 3D",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Comparar com a peça acabada: verde = na medida, azul = material restante, vermelho = fundo demais",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Mover o mouse para o lado de um contorno (o lado define a direção) · Esc encerra",
"Mit diesem Werkzeug kann nicht gefräst werden":"Não é possível fresar com esta ferramenta",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Com um macho de rosca use apenas o ciclo “Roscamento com macho” – um ciclo de furação o quebraria",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Com várias passadas, a profundidade da rosca é fresada em etapas que removem aproximadamente a mesma quantidade – poupa fresas de rosca pequenas e materiais duros. A passada de alívio percorre a última trajetória mais uma vez sem avanço radial.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Com „Ciclos de furação“ no programa NC, são emitidos ciclos do comando (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85); caso contrário, movimentos expandidos.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Com «Manter original», o original e sua imagem espelhada formam uma única malha; os pontos no plano de espelhamento são unidos – assim, uma metade aberta se torna uma peça fechada.",
