"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Somente contornos externos (pinos) funcionam como ciclo do comando",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Somente diâmetro (forma como esta ferramenta)",
"Nur Innenkonturen (Öffnungen)":"Somente contornos internos (aberturas)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Somente bolsões retangulares e circulares funcionam como ciclo do comando",
"Nur Skizze":"Somente esboço",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Usinar apenas o que uma fresa maior deixou nos cantos.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Percorrer novamente apenas os trechos do contorno que uma fresa maior não alcançou (cantos internos, locais estreitos). Sem arcos de entrada/saída, pontes e passes de acabamento; compensação no computador.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Somente onde a ferramenta de referência não alcançou: regiões planas em paralelo, regiões íngremes como linha d'água. Com uma ferramenta da lista, sua forma também conta – por exemplo, o que uma fresa toroidal deixa nos rebaixos.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Somente faces planas podem servir como plano de esboço.",
"Nur ebene Flächen können extrudiert werden":"Somente faces planas podem ser extrudadas",
"Nur ebene Flächen lassen sich ersetzen":"Somente faces planas podem ser substituídas",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Somente faces planas e cilíndricas (furos, pinos) podem ser deslocadas",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Somente faces planas voltadas para cima, em direção à ferramenta (horizontais neste setup).",
