"Nut":"Rasgo",
"Nut angetrieben":"Rasgo com ferramenta motorizada",
"Nut angetrieben (C-Achse)":"Rasgo com ferramenta motorizada (eixo C)",
"Nut liegt nicht am Teil":"O rasgo não está na peça",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Rasgo ao longo do eixo de rotação (p. ex. rasgo de chaveta) com uma fresa motorizada apontada para o eixo; o fuso principal mantém a peça como eixo C. Largura do rasgo = Ø da fresa. Z inicial/final em Z do modelo; se o rasgo chega até a face frontal, a fresa entra pela frente; caso contrário, penetra no início. Profundidade a partir do diâmetro externo.",
"Nutbreite bei Linien":"Largura do rasgo em linhas",
