"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"As arestas abertas são exibidas em vermelho. “Reparar” fecha os buracos.",
"Offene Linie in einer Skizze wählen":"Selecione uma linha aberta em um esboço",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Curvas abertas ou fechadas são extrudadas perpendicularmente ao esboço – o resultado é uma superfície (parede sem espessura). Com “Espessar” ou “Costurar”, ela se torna um sólido.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Curvas abertas ou fechadas são giradas em torno do eixo – o resultado é uma superfície, não um sólido.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Sem tecla própria, vale o padrão “{0}”.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Sem “Modelada”, a rosca é apenas representada (rápido). Modelada, a forma da rosca é realmente cortada, p. ex. para impressão 3D. Furo para M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP torneamento",
"Okuma OSP-M Fräsen":"Okuma OSP-M fresamento",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 não vão para coordenadas da máquina nesse comando (G53 cancela a compensação do comprimento da ferramenta) – recuo para a altura de segurança, nenhum retorno XY à referência emitido",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: nenhuma função de suavização emitida (G5.1 é Fanuc) – ajuste Hi-Cut/Super-NURBS na máquina",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: corretor+ferramenta+aresta de corte (p. ex. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (todas as funções)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: todas as funções. Núcleo Rust (truck, experimental): primitivas, extrusão, revolução, furo, padrão, espelhar, mover, escalar, combinar e exportação STEP – outras features são marcadas como “ainda não suportado”.",
