"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Projetar arestas e faces exige um sólido do núcleo padrão – silhueta do corpo e curvas de interseção também funcionam com malhas.",
