"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Relevo {0}: {1} mm é maior que 3 × a espessura da chapa – com parede vertical a chapa rasga.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Relevo: o contorno não é recortado, mas pressionado para fora da placa na altura indicada. Escareado estampado: a borda de um furo redondo é pressionada formando um cone de 90° – para parafusos de cabeça escareada em chapa fina (− para baixo: parafuso por cima).",
