"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Desbasta simultaneamente em 4 eixos de fora para dentro: uma espiral em torno do eixo A por passo (alternando em +X e −X), nunca mais fundo que a peça mais o sobremetal. Com fresa de topo ou esférica.",
