"Tasche Planfläche (C-Achse)":"Cavidade na face frontal (eixo C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Cavidade na circunferência a partir dos contornos fechados de um esboço situado ao longo do eixo de torneamento (os contornos internos permanecem como ilhas). O esboço é enrolado sobre o diâmetro; uma fresa de topo acionada, voltada para o eixo, desbasta de dentro para fora (Z e C se movem juntos; Fanuc: interpolação cilíndrica G7.1). A fresa penetra em rampa ao longo do anel mais interno.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Cavidade na face frontal a partir dos contornos fechados de um esboço (contornos internos permanecem como ilhas), com uma fresa de topo motorizada ao longo de Z. O desbaste vai de dentro para fora; a fresa penetra em rampa ao longo da trajetória mais interna e permanece embaixo dentro de um nível. X e C se movem juntos (Fanuc: interpolação polar G12.1). Profundidade a partir da face frontal.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Bolsão com ilha – o ciclo do comando não suporta ilhas",
