"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Opera de fato duas malhas fechadas entre si: as faces internas desaparecem e as arestas de interseção são remalhadas. O cálculo é feito apenas onde as duas malhas podem se encontrar – por isso uma malha grande com uma pequena intervenção é rápida. Se duas malhas grandes se sobrepõem por completo, use antes „Reduzir“.",
