"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Enrola as curvas do esboço no cilindro: X permanece X, a distância transversal ao eixo torna-se um arco no Ø de desenvolvimento (rotação A). O esboço deve ser paralelo ao eixo A, p. ex. em um plano tangente. A fresagem ocorre a uma profundidade fixa abaixo da superfície da peça – para gravações, textos e rasgos em volta da peça.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Como o contorno 3D, mas a ferramenta desce continuamente sem degraus – sem marcas de mergulho em paredes íngremes.",
