"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: A origem da peça Y/Z não está no eixo de rotação A (eixo em Y{1} Z{2}) – para 4 eixos simultâneos, coloque a origem da peça no eixo (ponto do bruto centro Y/Z)",
