"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Pós-processador sem o modelo “Eixo C e ferramenta motorizada ligados” – ligue o eixo C e o fuso da ferramenta manualmente",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: Pós-processador sem interpolação cilíndrica – Z e C se movem juntos; dependendo do comando, o avanço então não vale ao longo da trajetória. É melhor preencher o modelo „Interpolação cilíndrica ligada/desligada“",
