"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"“+” = a ferramenta será criada. Os dados de corte são valores de referência para metal duro ({0}){1}; refrigeração: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Encaixar uns nos outros“ coloca os recortes nos vãos e reentrâncias de seus vizinhos e nos recortes deles (sem girar 90°, apenas virados em 180°); a distância nunca é reduzida. Sem a marca, eles ficam em fileiras conforme o retângulo envolvente. Com „Esboço + corpos“ são criados corpos planos na espessura da chapa, que podem ser cortados na manufatura com contorno 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Interno/Externo” precisa de contornos fechados – fresar curvas abertas com “Sobre a curva”",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"“Concluir esboço” → Extrusão, Revolução ou Furo.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"“Esboço” → escolha o plano XY/XZ/YZ ou clique em uma face plana.",
