"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Verifique todo programa NC antes da primeira execução: na máquina em teste a seco (bloco a bloco, avanço rápido reduzido) ou em um simulador NC externo. A simulação aqui não substitui isso – uso por sua conta e risco, sem garantia.",
"⚠ Kollision bei {0} von {1} Stellungen, z. B. {2}":"⚠ Colisão em {0} de {1} posições, p. ex. {2}",
"⚠ Kreisbögen mit R statt I/J werden nicht unterstützt – I/J wird ausgegeben":"⚠ Arcos com R em vez de I/J não são suportados – I/J é emitido",
"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ Após a última alteração do corpo, não ficou claro qual aresta ou face é a referida. Verifique – se necessário, exclua e projete novamente.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ A lógica do programa (JavaScript) não é executada: verifique funções especiais, 4º/5º eixo, ciclos de apalpação e opções da máquina no editor de pós-processador.",
"⚠ {0} Abhängigkeit(en) nicht erfüllbar – Skizze überbestimmt oder widersprüchlich":"⚠ {0} restrição(ões) não pode(m) ser satisfeita(s) – esboço super-restrito ou contraditório",
