"✓ Keine Überschneidungen zwischen den Körpern.":"✓ Nenhuma interferência entre os corpos.",
"📚 = Bibliothek: eigene Postprozessoren stehen in allen Projekten zur Verfügung. Ein verwendeter wird ins Projekt kopiert, damit die Datei vollständig bleibt.":"📚 = biblioteca: pós-processadores próprios ficam disponíveis em todos os projetos. Um que esteja em uso é copiado para o projeto, para que o arquivo permaneça completo.",
"📚 Die Bibliothek hat eine andere Fassung dieses Postprozessors.":"📚 A biblioteca tem outra versão deste pós-processador.",
